/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

void rxt_toggle (void * arg)
{
	if (rxt.state != RXT_STATE_STOP)
	{		
	 	rxt_stop (0) ;
	}
	else
	{	
		rxt_start (0) ;
	}		
}

